% [order] GenericTrialCounterbalancer_GenerateOrder(args)
%
% Input:
%   condition_table             table of unique conditions, values in the columns used must be numeric or string
%   rules                       rules struct generated by GenericTrialCounterbalancer_InitializeRules with any overwrites
%   repetitions                 number of repetitions of each condition
%
% Output:
%   order                       [1xN] order of condition rows
%
function [order] = GenericTrialCounterbalancer_GenerateOrder(args)
arguments
    args.condition_table            table
    args.rules              (1,1)   struct
    args.repetitions        (1,1)   double
    args.fprintf_prefix     (1,1)   string = ""
end

%% Verify that args with no defaults have been provided
requiredFields = ["condition_table","rules","repetitions"];
missing = requiredFields(~isfield(args, requiredFields));
if ~isempty(missing)
    error("Missing required arguments: %s", strjoin(missing,", "))
end

%% Convert condition labels into numeric indices

args.condition_table = GenericTrialCounterbalancer_ConvertLabelsToIndices(condition_table = args.condition_table, ...
                                                                          rules =           args.rules ...
                                                                          );


%% Prep

% Counts
conditions_count = height(args.condition_table);
trials_count = conditions_count * args.repetitions;

% Field names
rules_order_names = string(fields(args.rules.order)');
rules_order_count = length(rules_order_names);
rules_perhalfcount_names = string(fields(args.rules.perhalfcount)');
rules_perhalfcount_count = length(rules_perhalfcount_names);

% Number of unique values per variable
for f = unique([rules_order_names rules_perhalfcount_names])
    variables_count.(f) = length(unique(args.condition_table.(f)));
end


%% Checks

% Confirm that conditions are all unique
if height(unique(args.condition_table, "rows")) ~= height(args.condition_table)
    error("conditions table contains duplicates")
end

% Check if order effect min/max are (likely) possible
for f = rules_order_names
    % check matrix size
    if any(size(args.rules.order.(f).min) ~= variables_count.(f))
        error("The size of rules.order.%s.min is incorrect", f)
    elseif any(size(args.rules.order.(f).max) ~= variables_count.(f))
        error("The size of rules.order.%s.max is incorrect", f)
    end

    % how many order pairs are there
    pairs_count = trials_count - 1;

    % verify that sum(min) <= pairs_count <= sum(max)
    if pairs_count < sum(args.rules.order.(f).min(:))
        error("The sum of rules.order.%s.min is too high", f)
    elseif pairs_count > sum(args.rules.order.(f).max(:))
        error("The sum of rules.order.%s.max is too low", f)
    end
    
    % verify that min <= max
    if any(args.rules.order.(f).min(:) > args.rules.order.(f).max(:))
        error("rules.order.%s.min > rules.order.%s.max in one or more cells", f, f)
    end

    % verify that diagonals are possible
    total_reps = conditions_count / variables_count.(f) * args.repetitions;
    max_consecutive_duplicates = total_reps - 1;
    diag_values = args.rules.order.(f).max(eye(variables_count.(f))==1);
    diag_values = diag_values(~isinf(diag_values));
    if any(diag_values > max_consecutive_duplicates)
        error("rules.order.%s.max contains one or more impossible values on the diagonal", f)
    end
end

% Check per-half count min/max are possible
for f = rules_perhalfcount_names
    % how many times do the levels of this variable each happen in a run?
    total_reps = conditions_count / variables_count.(f) * args.repetitions;

    % min cannot be more than half of the repetitions (both halves of a run cannot contain more than half of the reps)
    if args.rules.perhalfcount.(f).min > floor(total_reps/2)
        error("rules.perhalfcount.%s.min is not possible", f)
    end

    % max cannot be less than half of the repetitions (both halves of a run cannot contain less than half of the reps)
    if args.rules.perhalfcount.(f).max < ceil(total_reps/2)
        error("rules.perhalfcount.%s.max is not possible", f)
    end
end


%% Generate order

% loop until successful
loop_counter = 0;
while 1
loop_counter = loop_counter + 1;

% initialize conditions
order = nan(1, trials_count);
cond_remain = ones(1, conditions_count) * args.repetitions;

% initialize order effects matrices
for f = rules_order_names
    order_effects.(f) = zeros(variables_count.(f), variables_count.(f));
end

% initialize perhalfcount counters
trials_midpoint = floor(trials_count/2);
for f = rules_perhalfcount_names
    perhalfcounts.(f) = zeros(1, variables_count.(f));
end

% default to success
success = true;

% trial loop
for trial = 1:trials_count
    if trial == 1
        % choose first condition
        if isnan(args.rules.first_condition_index) || isempty(args.rules.first_condition_index)
            % not predefined, choose randomly
            selected = randperm(conditions_count,1);
        else
            % use predefined
            selected = args.rules.first_condition_index;
        end
    else
        % choose next trial
        %   -for each order rule, identify both the valid options and most-balanced options
        %   -combine the above and then randomly select from the overall best valid options
        %   -if there are ever no valid options, stop and restart

        % initialize all conditions as best move for each rule
        best = true(rules_order_count, conditions_count);

        % initialize all conditions as a valid next move
        valid = true(1, conditions_count);

        % invalidate any conditions with no remaining reps
        valid(~cond_remain) = false;

        % invalidate any conditions that cannot occur in this half
        for f = rules_perhalfcount_names
            % which variable levels can not be selected again in the first half
            invalid_indices = find(perhalfcounts.(f) >= args.rules.perhalfcount.(f).max);
            
            % which conditions have these levels
            invalid_conditions = any(args.condition_table.(f) == invalid_indices, 2);
            
            % invalidate
            valid(invalid_conditions) = false;
        end

        % for each order rule, update valid and check for best options
        for f_ind = 1:rules_order_count
            f = rules_order_names(f_ind);

            % what was the prior value
            prior_index = args.condition_table.(f)(order(trial-1));

            % what is the status for following that prior index
            status = order_effects.(f)(prior_index,:);

            % invalidate options that cannot follow the prior index
            invalid = status >= args.rules.order.(f).max(prior_index,:);
            invalid_indices = find(invalid);
            invalid_conditions = any(args.condition_table.(f) == invalid_indices, 2);
            valid(invalid_conditions) = false;

            % measure how balanced each option would be
            options_min = min(status(~invalid));
            options_range = range(status(~invalid));
            if options_range
                options_balance = 1 - ((status - options_min) / options_range);
                best(f_ind,:) = options_balance(args.condition_table.(f));
            end
        end

        % stop and restart if nothing is valid
        if ~any(valid)
            success = false;
            fprintf("%sAttempt %d ran out of options at trial %d of %d\n", args.fprintf_prefix, loop_counter, trial, trials_count);
            break;
        end

        % set invalid conditions to NOT best
        best(:,~valid) = false;

        % count how many rules each condition is best in
        best_sum = sum(best, 1);

        % randomly select from best overall
        options = find((best_sum==max(best_sum)) & valid);
        selected = options(randperm(length(options),1));
    end

    % verify that there are remaining reps
    if ~cond_remain(selected)
        error("Attempted to add a condition with no remaining reps. This should not be possible.")
    end

    % add selected trial
    order(trial) = selected;
    cond_remain(selected) = cond_remain(selected) - 1;

    % update order matrices
    if trial > 1
        for f = rules_order_names
            prior = args.condition_table.(f)(order(trial-1));
            this = args.condition_table.(f)(order(trial));
            order_effects.(f)(prior,this) = order_effects.(f)(prior,this) + 1;
        end
    end

    % update half counts
    if trial == trials_midpoint
        % reinitialize perhalfcount counters
        for f = rules_perhalfcount_names
            perhalfcounts.(f) = zeros(1, variables_count.(f));
        end
    else
        % add to counts
        for f = rules_perhalfcount_names
            ind = args.condition_table.(f)(selected);
            perhalfcounts.(f)(ind) = perhalfcounts.(f)(ind) + 1;
        end
    end

end

% restart?
if ~success
    continue
end

% verify that order effect rules were followed
for f = rules_order_names
    if any(order_effects.(f)(:) < args.rules.order.(f).min(:))
        % error("Did not satisfy rules.order.%s.min. This should not be possible!", f);
        fprintf("%sAttempt %d found an order that kept under the max order effects values, but did not satisfy the min values.\n", args.fprintf_prefix, loop_counter);
        success = false;
        break
    elseif any(order_effects.(f)(:) > args.rules.order.(f).max(:))
        error("Did not satisfy rules.order.%s.max. This should not be possible!", f);
    end
end

% verify that per-half count rules were followed
for f = rules_perhalfcount_names
    for half = 1:2
        if half==1
            values = args.condition_table.(f)(order(1:trials_midpoint));
        else
            values = args.condition_table.(f)(order((trials_midpoint+1):trials_count));
        end

        counts = arrayfun(@(x) sum(values==x), 1:variables_count.(f));
        if any(counts < args.rules.perhalfcount.(f).min)
            % error("Did not satisfy rules.perhalfcount.%s.min. This should not be possible!", f);
            fprintf("%sAttempt %d found an order that kept under the max per-half counts, but did not satisfy the min values.\n", args.fprintf_prefix, loop_counter);
            success = false;
            break
        elseif any(counts > args.rules.perhalfcount.(f).max)
            error("Did not satisfy rules.perhalfcount.%s.max. This should not be possible!", f);
        end
    end
end

% restart?
if ~success
    continue
end

% success! end the loop
break

end

%% Success
fprintf("%sFound solution after %d attempt(s):%s\n", args.fprintf_prefix, loop_counter, sprintf(" %d", order));